// UI language and runtime translation.
// English strings in the game are not converted to keys one by one; they are replaced at display time: Pixi text and DOM text nodes go through tr().
// zh.json is generated by tools/i18n/build-dict.mjs: English source → Chinese; entries containing {0} {1} are templates.

export type Lang = "en" | "zh";

const STORAGE_KEY = "sfh3.lang";
const CJK = /[　-〿㐀-鿿＀-￯]/;

function detectLang(): Lang {
  try {
    const q = new URLSearchParams(location.search).get("lang");
    if (q === "zh" || q === "en") {
      localStorage.setItem(STORAGE_KEY, q);
      return q;
    }
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === "zh" || saved === "en") return saved;
  } catch {
  }
  const langs = typeof navigator !== "undefined" ? navigator.languages ?? [navigator.language] : [];
  return langs.some((l) => /^zh\b/i.test(l)) ? "zh" : "en";
}

export const lang: Lang = typeof window === "undefined" ? "en" : detectLang();

/** Switching language reloads the whole page, so the UI and fonts are rebuilt in the new language. */
export function setLang(next: Lang, beforeReload?: () => void): void {
  if (next === lang) return;
  try {
    localStorage.setItem(STORAGE_KEY, next);
  } catch {
  }
  beforeReload?.();
  location.reload();
}

type Template = { re: RegExp; zh: string; order: number[] };

const exact = new Map<string, string>();
const lower = new Map<string, string>();
const templates: Template[] = [];
const cache = new Map<string, string>();
const missing = new Set<string>();
let active = false;

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function compileTemplate(en: string, zh: string): Template | null {
  const parts = en.split(/(\{\d+\})/);
  const order: number[] = [];
  let src = "";
  for (const p of parts) {
    const m = /^\{(\d+)\}$/.exec(p);
    if (m) {
      order.push(Number(m[1]));
      src += "([\\s\\S]*?)";
    } else src += escapeRe(p);
  }
  if (!/[A-Za-z]/.test(en.replace(/\{\d+\}/g, ""))) return null;
  return { re: new RegExp(`^${src}$`, "i"), zh, order };
}

/** Load the Chinese dictionary. Does nothing for the English UI. */
export async function initI18n(): Promise<void> {
  if (lang !== "zh") return;
  const dict = (await import("./zh.json")).default as Record<string, string>;
  const list: { t: Template; weight: number }[] = [];
  for (const [en, zh] of Object.entries(dict)) {
    if (/\{\d+\}/.test(en)) {
      const t = compileTemplate(en, zh);
      if (t) list.push({ t, weight: en.replace(/\{\d+\}/g, "").length });
    } else {
      exact.set(en, zh);
      const k = en.toLowerCase();
      lower.set(k, lower.has(k) && lower.get(k) !== zh ? lower.get(k)! : zh);
    }
  }
  // Templates with longer literal parts are more specific, so match them first
  list.sort((a, b) => b.weight - a.weight);
  for (const { t } of list) templates.push(t);
  active = true;
  document.documentElement.lang = "zh-CN";
  // To find missing translations, run sfh3I18n.missing() in the console
  (window as unknown as Record<string, unknown>).sfh3I18n = { missing: missingStrings, tr };
}

export function isZh(): boolean {
  return active;
}

function lookup(s: string, depth: number): string | null {
  const hit = exact.get(s) ?? lower.get(s.toLowerCase());
  if (hit !== undefined) return hit;

  // Keep leading and trailing whitespace; only translate the middle
  const m = /^(\s*)([\s\S]*?)(\s*)$/.exec(s)!;
  if (m[1] || m[3]) {
    const core = m[2] && lookup(m[2], depth);
    if (core != null) return m[1] + core + m[3];
  }

  for (const t of templates) {
    const r = t.re.exec(s);
    if (!r) continue;
    let out = t.zh;
    t.order.forEach((n, i) => {
      const arg = r[i + 1];
      const v = depth < 2 && /[A-Za-z]/.test(arg) ? lookup(arg, depth + 1) ?? withSuffix(arg, depth + 1) : arg;
      out = out.split(`{${n}}`).join(v);
    });
    return out;
  }

  // Translate multi-line text line by line
  if (s.includes("\n")) {
    const lines = s.split("\n");
    let changed = false;
    const out = lines.map((l) => {
      if (!/[A-Za-z]/.test(l)) return l;
      const v = lookup(l, depth);
      if (v != null) changed = true;
      return v ?? l;
    });
    if (changed) return out.join("\n");
  }
  return null;
}

/** When a template argument has a number stuck to it (e.g. "Mercenary +1"), only translate the words before it. */
function withSuffix(arg: string, depth: number): string {
  const m = /^(.*?[A-Za-z])(\s*[+\-]?\d[\s\S]*)$/.exec(arg);
  const head = m && lookup(m[1], depth);
  return head != null ? head + m![2] : arg;
}

/** Replace English text to be displayed with the current language. Returns it unchanged if not found. */
export function tr(s: string): string {
  if (!active || !s || !/[A-Za-z]/.test(s)) return s;
  const c = cache.get(s);
  if (c !== undefined) return c;
  const v = lookup(s, 0);
  if (v == null && !CJK.test(s) && missing.size < 3000) missing.add(s);
  const out = v ?? s;
  if (cache.size > 20000) cache.clear();
  cache.set(s, out);
  return out;
}

const loose = new Map<string, string>();
const squash = (s: string) => s.replace(/\s+/g, " ").trim().toLowerCase();

/** Look up a whole sentence, ignoring whitespace differences. Returns null if not found (not recorded as missing). Used for paragraphs rebuilt from fragments. */
export function trLoose(s: string): string | null {
  if (!active) return null;
  if (!loose.size) for (const [en, zh] of exact) loose.set(squash(en), zh);
  return loose.get(squash(s)) ?? null;
}

/** For testing and debugging: list English strings that were displayed but are not in the dictionary. */
export function missingStrings(): string[] {
  return [...missing];
}
